package com.braseiro.dnd5e;
import java.util.HashSet;import org.json.JSONArray;import org.json.JSONObject;
/** Exact dry-run validator. Uses the same source-bound authority probes as runtime registration and rejects duplicate identities. */
public final class AuthorizedContentBatchValidationEngine{
 private AuthorizedContentBatchValidationEngine(){}
 public static JSONObject validate(JSONArray rows){JSONObject o=new JSONObject();JSONArray ready=new JSONArray(),blocked=new JSONArray();HashSet<String> seen=new HashSet<>();int n=rows==null?0:rows.length();try{for(int i=0;i<n;i++){JSONObject x=rows.optJSONObject(i),r=check(x);String key=r.optString("kind")+"\u0000"+r.optString("name");if(r.optBoolean("ready",false)&&!seen.add(key))r=no(r.optString("kind"),r.optString("name"),"duplicate_identity_in_batch");(r.optBoolean("ready",false)?ready:blocked).put(r);}return o.put("requested",n).put("ready",ready.length()).put("blocked",blocked.length()).put("ready_records",ready).put("blocked_records",blocked).put("all_ready",blocked.length()==0).put("dry_run",true).put("mutated_registry",false).put("authority_validation","runtime_exact_source_bound");}catch(Exception e){try{return o.put("requested",n).put("ready",ready.length()).put("blocked",blocked.length()+1).put("all_ready",false).put("dry_run",true).put("mutated_registry",false);}catch(Exception ignored){return o;}}}
 private static JSONObject check(JSONObject x){if(x==null)return no("","","missing_record");String k=norm(x.optString("kind")),n=x.optString("name").trim();if("statblock_scope".equals(k)){JSONObject s=x.optJSONObject("scope");return s!=null&&s.optString("id").trim().length()>=3&&!s.optString("source_book").trim().isEmpty()&&!s.optString("source_locator").trim().isEmpty()?yes(k,s.optString("id")):no(k,n,"incomplete_scope_record");}if("statblock".equals(k)){JSONObject s=x.optJSONObject("statblock");if(s==null)s=x.optJSONObject("record");JSONObject a=CompiledStatblockEngine.authorityCheck(s);return a.optBoolean("authorized",false)?yes(k,a.optString("id")):no(k,n,a.optString("authority","blocked_statblock_authority"));}if(!"spell".equals(k)&&!"item".equals(k)&&!"subclass".equals(k)&&!"feat".equals(k))return no(k,n,"unsupported_kind");JSONObject m=x.optJSONObject("mechanics"),b=x.optJSONObject("mechanical_basis");if(m==null||m.length()==0)return no(k,n,"missing_mechanics");JSONObject a=CompiledContentMechanicsEngine.authorityCheck(k,n,b);return a.optBoolean("authorized",false)?yes(k,n):no(k,n,a.optString("authority","blocked_missing_authorized_source"));}
 private static JSONObject yes(String k,String n){/*BR_JSON_WRAP_106*/try{return new JSONObject().put("kind",k).put("name",n).put("ready",true);}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}private static JSONObject no(String k,String n,String reason){/*BR_JSON_WRAP_106*/try{return new JSONObject().put("kind",k).put("name",n).put("ready",false).put("reason",reason);}catch(RuntimeException __brJsonRuntime106){throw __brJsonRuntime106;}catch(Exception __brJsonChecked106){throw new IllegalStateException(__brJsonChecked106);}}private static String norm(String s){String x=s==null?"":s.trim().toLowerCase();return "character_option".equals(x)?"subclass":x;}
}
